// session's 240-byte cipher material. Native word groups are little endian.
func TransformAndroidSPIMBody(body [240]byte) (output [240]byte) {
	feedback := [4]uint32{0xff115fce, 0x94a9098a, 0xb7681d4a, 0x4cad1e61}
	for i := 0; i < 15; i++ {
		var input [16]byte
		copy(input[:], body[16*i:16*i+16])
		words, next := androidSPIMRound(input, feedback)
		feedback = next
		for j, w := range words {
			for k := 0; k < 4; k++ {
				output[16*i+4*j+k] = byte(w >> (8 * k))
			}
		}
	}
	return
}
